// Tilda шлёт поля формы в body. Имена полей задаются в самой форме.
// Забираем и то, что может прийти из обычного fetch (JSON).
const wh = $('Webhook — форма Tilda').first().json;
const b = wh.body || {};

const pick = (...keys) => {
  for (const k of keys) {
    const hit = Object.keys(b).find(x => x.toLowerCase() === k.toLowerCase());
    if (hit && String(b[hit]).trim()) return String(b[hit]).trim();
  }
  return '';
};

const name    = pick('name', 'Name', 'имя', 'fio') || 'Без имени';
const phone   = pick('phone', 'Phone', 'tel', 'телефон');
const email   = pick('email', 'Email', 'почта');
const comment = pick('comment', 'message', 'text', 'комментарий', 'задача');
const form    = pick('formname', 'formid', 'form') || 'Форма на сайте';
const page    = pick('page', 'referer', 'url') || wh.headers?.referer || '';

// id заявки — по нему потом находим строку в таблице при нажатии кнопки
const lead_id = 'L' + Date.now().toString(36).toUpperCase();

const ts = new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' });

// Телефон в тексте Telegram делает кликабельным сам — набор в один тап
const lines = [
  '🔥 <b>Новая заявка</b>',
  '',
  `<b>Имя:</b> ${name}`,
  phone   ? `<b>Телефон:</b> ${phone}` : null,
  email   ? `<b>Email:</b> ${email}` : null,
  comment ? `<b>Комментарий:</b> ${comment}` : null,
  '',
  `<i>${form} · ${ts} МСК · ${lead_id}</i>`
].filter(Boolean);

const digits = phone.replace(/\D/g, '');

return [{ json: { lead_id, name, phone, email, comment, form, page, ts, digits, text: lines.join('\n') } }];

