={{ JSON.stringify({
  chat_id: $('Config — сюда вставить токены').first().json.tg_chat_id,
  text: $json.text,
  parse_mode: 'HTML',
  reply_markup: {
    inline_keyboard: [
      [
        { text: '✅ Взял в работу', callback_data: 'work|' + $json.lead_id },
        { text: '💤 Позже',        callback_data: 'later|' + $json.lead_id }
      ],
      [
        { text: '❌ Отказ', callback_data: 'deny|' + $json.lead_id }
      ],
      ...($json.digits ? [[
        { text: '💬 Написать в WhatsApp', url: 'https://wa.me/' + $json.digits }
      ]] : [])
    ]
  }
}) }}
